"""C1 unresolved then administratively continued C2 pass cannot advance SOLO state."""
from __future__ import annotations
import json, uuid
from datetime import datetime, timezone
from sqlalchemy import select
from solo_harness.bootstrap import bootstrap
from solo_harness.config import get_settings
from solo_harness.db.engine import make_session_factory
from solo_harness.db.models import AssessmentInstance, AssessmentResponse, Attempt, LLMCall, Session, V04Evaluation
from solo_harness.runtime.engine import SessionRuntime
from solo_harness.runtime.v04_execution import finalize_v04_evaluation
from solo_harness.runtime.v04_native import SubjectiveJudgment

def main():
 c=get_settings(); d=make_session_factory(c.database_url)(); r=SessionRuntime(bootstrap(c)); source=d.scalar(select(AssessmentInstance).where(AssessmentInstance.status=="CLOSED").order_by(AssessmentInstance.closed_at.desc())); sr=d.scalar(select(AssessmentResponse).where(AssessmentResponse.assessment_instance_id==source.id)); s=r.create_session(d,d.get(Session,source.session_id).study_version_id,build_id="formal-gate",institutional_id="formal-gate-"+uuid.uuid4().hex[:10],commit=False); c1=d.get(Attempt,s.current_attempt_id); initial=s.formal_state_id; c1.status="FAILED"; c1.passed=False; s.phase="SECTION_COMPLETE"; r.complete_section(d,s,c1,"UNRESOLVED",False); r.advance_section(d,s.id); a=d.get(Attempt,s.current_attempt_id)
 item=AssessmentInstance(session_id=s.id,attempt_id=a.id,transition_id=a.transition_id,assessment_family_id=source.assessment_family_id,assessment_form_id=source.assessment_form_id+"-gate",status="AWAITING_EVALUATION",candidate_form_ids=source.candidate_form_ids,selection_method="FAULT",selection_audit={},blueprint_snapshot=source.blueprint_snapshot,resolved_component_ids=source.resolved_component_ids,frozen_public_snapshot=source.frozen_public_snapshot,frozen_private_snapshot=source.frozen_private_snapshot,frozen_package_fingerprint=source.frozen_package_fingerprint,frozen_schema_version=source.frozen_schema_version,frozen_metadata_snapshot=source.frozen_metadata_snapshot,delivery_status="DEVELOPMENT_ONLY",frozen_at=datetime.now(timezone.utc)); d.add(item); d.flush(); answers={x['id']:x['correct_option_id'] for x in item.frozen_private_snapshot['mcqs']}; resp=AssessmentResponse(assessment_instance_id=item.id,response_text=sr.response_text,response_format="plain",client_action_id=uuid.uuid4(),structured_response={"mcq_answers":answers},response_schema_version="v04.native.2"); d.add(resp); a.status="AWAITING_EVALUATION"; s.phase="ASSESSMENT_AWAITING_EVALUATION"; call=LLMCall(session_id=s.id,attempt_id=a.id,assessment_instance_id=item.id,purpose="JUDGE",status="SUCCEEDED",retry_group_id=uuid.uuid4(),retry_number=0,provider="fault",model="fault",generation_parameters={},request_payload={},request_body_text="{}"); d.add(call); d.commit(); j=SubjectiveJudgment(gradable_status="GRADABLE",subjective_points=1,observed_solo_structure="multi",material_correctness="correct",criterion_evidence=[],misconception_evidence=[],verbatim_quotes=[sr.response_text[:30]],alternative_reasoning_used=False,unverified_claims=[],review_reason=None,score_justification="controlled pass"); finalize_v04_evaluation(d,r,s.id,j,call.id); e=d.scalar(select(V04Evaluation).where(V04Evaluation.assessment_response_id==resp.id)); second=finalize_v04_evaluation(d,r,s.id,j,call.id); result={"transition":a.transition_id,"assessment_passed":e.passed,"formal_state_before":initial,"formal_state_after":d.get(Session,s.id).formal_state_id,"advanced":a.formal_state_after_id!=initial,"same_evaluation":second.id==e.id,"evaluation_count":len(d.scalars(select(V04Evaluation).where(V04Evaluation.assessment_response_id==resp.id)).all())}; assert result['transition']=="C2" and result['assessment_passed'] and not result['advanced'] and result['same_evaluation'] and result['evaluation_count']==1; (c.research_data_dir/"formal_advancement_gate_trace.json").write_text(json.dumps(result,indent=2),encoding="utf-8"); print(json.dumps(result))
if __name__=="__main__": main()
